class RelationshipModel(models.Model):
    def required_related_objects_errors(
        cls, output_for="ui", initial_data=None, relationships_key_specified=False, instance=None
    ):
        """
        Args:
            output_for (str): either "ui" or "api" depending on usage
            initial_data (dict): submitted form/serializer data to validate against
            relationships_key_specified (bool): if the "relationships" key was provided or not
            instance (Optional[BaseModel]): an optional model instance to validate against
        Returns:
            (list[dict]): List of field error dicts if any are found
        """
        required_relationships = Relationship.objects.get_required_for_model(cls)
        relationships_field_errors = {}
        for relation in required_relationships:
            opposite_side = RelationshipSideChoices.OPPOSITE[relation.required_on]
            if relation.skip_required(cls, opposite_side):
                continue
            if relation.has_many(opposite_side):
                num_required_verbose = "at least one"
            else:
                num_required_verbose = "a"
            if output_for == "api":
                if (
                    getattr(instance, "present_in_database", False) is True
                    and initial_data.get(relation, {}).get(opposite_side, {}) == {}
                    and not relationships_key_specified
                ):
                    filter_kwargs = {"relationship": relation, f"{relation.required_on}_id": instance.pk}
                    if RelationshipAssociation.objects.filter(**filter_kwargs).exists():
                        continue
            required_model_class = getattr(relation, f"{opposite_side}_type").model_class()
            required_model_meta = required_model_class._meta
            cr_field_name = f"cr_{relation.key}__{opposite_side}"
            name_plural = cls._meta.verbose_name_plural
            field_key = relation.key if output_for == "api" else cr_field_name
            field_errors = {field_key: []}
            if not required_model_class.objects.exists():
                hint = (
                    f"You need to create {num_required_verbose} {required_model_meta.verbose_name} "
                    f"before instantiating a {cls._meta.verbose_name}."
                )
                if output_for == "ui":
                    try:
                        add_url = reverse(get_route_for_model(required_model_class, "add"))
                        hint = (
                            f"<a target='_blank' href='{add_url}'>Click here</a> to create "
                            f"a {required_model_meta.verbose_name}."
                        )
                    except NoReverseMatch:
                        pass
                elif output_for == "api":
                    try:
                        api_post_url = reverse(get_route_for_model(required_model_class, "list", api=True))
                        hint = f"Create a {required_model_meta.verbose_name} by posting to {api_post_url}"
                    except NoReverseMatch:
                        pass
                error_message = mark_safe(
                    f"{name_plural[0].upper()}{name_plural[1:]} require "
                    f"{num_required_verbose} {required_model_meta.verbose_name}, but no "
                    f"{required_model_meta.verbose_name_plural} exist yet. {hint}"
                )
                field_errors[field_key].append(error_message)
            if initial_data is not None:
                supplied_data = []
                if output_for == "ui":
                    supplied_data = initial_data.get(field_key, [])
                elif output_for == "api":
                    supplied_data = initial_data.get(relation, {}).get(opposite_side, {})
                if not supplied_data:
                    if output_for == "ui":
                        field_errors[field_key].append(
                            f"You need to select {num_required_verbose} {required_model_meta.verbose_name}."
                        )
                    elif output_for == "api":
                        field_errors[field_key].append(
                            f'You need to specify ["relationships"]["{relation.key}"]["{opposite_side}"]["objects"].'
                        )
            if len(field_errors[field_key]) > 0:
                relationships_field_errors[field_key] = field_errors[field_key]
        return relationships_field_errors
class DynamicGroup(OrganizationalModel):
    def _map_filter_fields(self):
        """Return all FilterForm fields in a dictionary."""
        if not self._set_object_classes(self.model):
            return {}
        modelform = self.form_class()
        modelform_fields = modelform.fields
        filterform = self.filterform_class()
        filterform_fields = filterform.fields
        filterset = self.filterset_class()
        filterset_fields = filterset.filters
        dynamic_group_filter_fields = getattr(self.model, "dynamic_group_filter_fields", {})
        skip_missing_fields = getattr(self.model, "dynamic_group_skip_missing_fields", False)
        skip_method_filters = True
        if not skip_missing_fields:
            missing_fields = set(modelform_fields).difference(filterform_fields)
        else:
            logger.debug("Will not add missing form fields due to model %s meta option.", self.model)
            missing_fields = set()
        for missing_field in missing_fields:
            if missing_field.startswith(self.exclude_filter_fields):
                logger.debug("Skipping excluded form field: %s", missing_field)
                continue
            if missing_field in dynamic_group_filter_fields:
                mapped_field = dynamic_group_filter_fields[missing_field]
                if mapped_field in filterform_fields:
                    logger.debug(
                        "Skipping missing form field %s; mapped to %s filter field", missing_field, mapped_field
                    )
                    continue
            try:
                filterset_field = filterset_fields[missing_field]
            except KeyError:
                logger.debug("Skipping %s: doesn't have a filterset field", missing_field)
                continue
            modelform_field = modelform_fields[missing_field]
            if isinstance(modelform_field, forms.CharField):
                new_modelform_field = filterset_field.field
                modelform_field = new_modelform_field
            if isinstance(modelform_field, forms.BooleanField):
                new_modelform_field = filterset_field.field
                new_modelform_field.widget = modelform_field.widget
                modelform_field = new_modelform_field
            if isinstance(modelform_field, forms.NullBooleanField):
                modelform_field.widget = StaticSelect2(choices=BOOLEAN_WITH_BLANK_CHOICES)
            if isinstance(modelform_field, DynamicModelChoiceField):
                modelform_field = filterset_field.field
            modelform_field.required = False
            modelform_field.widget.attrs.pop("required", None)
            modelform_field.initial = None
            to_field_name = filterset_field.extra.get("to_field_name")
            if to_field_name is not None:
                modelform_field.to_field_name = to_field_name
            logger.debug("Added %s (%s) to filter fields", missing_field, modelform_field.__class__.__name__)
            filterform_fields[missing_field] = modelform_field
        for filterset_field_name, filterset_field in filterset_fields.items():
            if skip_method_filters and filterset_field.method is not None:
                if hasattr(filterset, "generate_query_" + filterset_field.method):
                    logger.debug(
                        "Keeping %s for filterform: has a `generate_query_` filter method", filterset_field_name
                    )
                    continue
                filterform_fields.pop(filterset_field_name, None)
                logger.debug("Deleting %s from filterform: has a filter method", filterset_field_name)
        return_fields = {}
        for field_name, filter_field in filterform_fields.items():
            if field_name.startswith(self.exclude_filter_fields):
                logger.debug("Skipping excluded filter field: %s", field_name)
                continue
            if field_name not in filterset_fields:
                logger.debug("Skipping removed filterset field: %s", field_name)
                continue
            return_fields[field_name] = filter_field
        return return_fields
    def members_cached(self):
        """Return the member objects for this group, cached if available."""
        unpickled_query = None
        try:
            cached_query = cache.get(self.members_cache_key)
            if cached_query is not None:
                unpickled_query = pickle.loads(cached_query)
        except pickle.UnpicklingError:
            logger.warning("Failed to unpickle cached members for %s", self)
        finally:
            if unpickled_query is None:
                unpickled_query = self.members.all()
                cached_query = pickle.dumps(unpickled_query)
                cache.set(
                    self.members_cache_key, cached_query, get_settings_or_config("DYNAMIC_GROUPS_MEMBER_CACHE_TIMEOUT")
                )
        return unpickled_query
