        elif "token" in self.consumer_config["response_type"]:
            _log_info("Expect Access Token Response")
            atr = self.parse_response(
                AccessTokenResponse,
                info=query,
                sformat="urlencoded",
                keyjar=self.keyjar,
                **kwargs,
            )
            if isinstance(atr, ErrorResponse):
                raise TokenError(atr.get("error"), atr)
