        self, query="", **kwargs
    ) -> Union[
        http_util.BadRequest,
        Tuple[
            Optional[AuthorizationResponse],
            Optional[AccessTokenResponse],
            Optional[IdToken],
        ],
    ]:
        """
        Parse authorization response from server.
        Couple of cases
        ["code"]
        ["code", "token"]
        ["code", "id_token", "token"]
        ["id_token"]
        ["id_token", "token"]
        ["token"]
        """
        _log_info = logger.info
        logger.debug("- authorization -")
        if not query:
