                        col_source = cte.original
                    elif isinstance(cte.original, selectable.CompoundSelect):
                        col_source = cte.original.selects[0]
                    else:
                        assert False
                    recur_cols = [
                        c
                        for c in util.unique_list(col_source.inner_columns)
                        if c is not None
