                  t.relname,
                  i.relname
            """
        t = sql.text(IDX_SQL).columns(
            relname=sqltypes.Unicode, attname=sqltypes.Unicode
        )
        c = connection.execute(t, table_oid=table_oid)
        indexes = defaultdict(lambda: defaultdict(dict))
        sv_idx_name = None
        for row in c.fetchall():
            (
                idx_name,
