            Deferred: Results in `None` if we have not previously responded to
            this transaction or a 2-tuple of `(int, dict)` representing the
            response code and response body.
        """
        if not transaction.transaction_id:
            raise RuntimeError("Cannot persist a transaction with no "
                               "transaction_id")
        return self.store.get_received_txn_response(
            transaction.transaction_id, transaction.origin
        )
class FederationSendServlet(BaseFederationServlet):
    def on_PUT(self, origin, content, query, transaction_id):
        """ Called on PUT /send/<transaction_id>/
        Args:
            request (twisted.web.http.Request): The HTTP request.
            transaction_id (str): The transaction_id associated with this
                request. This is *not* None.
        Returns:
            Deferred: Results in a tuple of `(code, response)`, where
            `response` is a python dict to be converted into JSON that is
            used as the response body.
        """
        try:
            transaction_data = content
            logger.debug(
                "Decoded %s: %s",
                transaction_id, str(transaction_data)
            )
            logger.info(
                "Received txn %s from %s. (PDUs: %d, EDUs: %d)",
                transaction_id, origin,
                len(transaction_data.get("pdus", [])),
                len(transaction_data.get("edus", [])),
            )
            transaction_data.update(
                transaction_id=transaction_id,
                destination=self.server_name
            )
        except Exception as e:
            logger.exception(e)
            defer.returnValue((400, {"error": "Invalid transaction"}))
            return
        try:
            code, response = yield self.handler.on_incoming_transaction(
                transaction_data
            )
        except Exception:
            logger.exception("on_incoming_transaction failed")
            raise
        defer.returnValue((code, response))
class FederationHandler(BaseHandler):
    def maybe_backfill(self, room_id, current_depth):
        """Checks the database to see if we should backfill before paginating,
        and if so do.
        """
        extremities = yield self.store.get_oldest_events_with_depth_in_room(
            room_id
        )
        if not extremities:
            logger.debug("Not backfilling as no extremeties found.")
            return
        sorted_extremeties_tuple = sorted(
            extremities.items(),
            key=lambda e: -int(e[1])
        )
        max_depth = sorted_extremeties_tuple[0][1]
        extremities = dict(sorted_extremeties_tuple[:5])
        if current_depth > max_depth:
            logger.debug(
                "Not backfilling as we don't need to. %d < %d",
                max_depth, current_depth,
            )
            return
        curr_state = yield self.state_handler.get_current_state(room_id)
        def get_domains_from_state(state):
            """Get joined domains from state
            Args:
                state (dict[tuple, FrozenEvent]): State map from type/state
                    key to event.
            Returns:
                list[tuple[str, int]]: Returns a list of servers with the
                lowest depth of their joins. Sorted by lowest depth first.
            """
            joined_users = [
                (state_key, int(event.depth))
                for (e_type, state_key), event in iteritems(state)
                if e_type == EventTypes.Member
                and event.membership == Membership.JOIN
            ]
            joined_domains = {}
            for u, d in joined_users:
                try:
                    dom = get_domain_from_id(u)
                    old_d = joined_domains.get(dom)
                    if old_d:
                        joined_domains[dom] = min(d, old_d)
                    else:
                        joined_domains[dom] = d
                except Exception:
                    pass
            return sorted(joined_domains.items(), key=lambda d: d[1])
        curr_domains = get_domains_from_state(curr_state)
        likely_domains = [
            domain for domain, depth in curr_domains
            if domain != self.server_name
        ]
        @defer.inlineCallbacks
        def try_backfill(domains):
            for dom in domains:
                try:
                    yield self.backfill(
                        dom, room_id,
                        limit=100,
                        extremities=extremities,
                    )
                    defer.returnValue(True)
                except SynapseError as e:
                    logger.info(
                        "Failed to backfill from %s because %s",
                        dom, e,
                    )
                    continue
                except CodeMessageException as e:
                    if 400 <= e.code < 500:
                        raise
                    logger.info(
                        "Failed to backfill from %s because %s",
                        dom, e,
                    )
                    continue
                except NotRetryingDestination as e:
                    logger.info(e.message)
                    continue
                except FederationDeniedError as e:
                    logger.info(e)
                    continue
                except Exception as e:
                    logger.exception(
                        "Failed to backfill from %s because %s",
                        dom, e,
                    )
                    continue
            defer.returnValue(False)
        success = yield try_backfill(likely_domains)
        if success:
            defer.returnValue(True)
        tried_domains = set(likely_domains)
        tried_domains.add(self.server_name)
        event_ids = list(extremities.keys())
        logger.debug("calling resolve_state_groups in _maybe_backfill")
        resolve = logcontext.preserve_fn(
            self.state_handler.resolve_state_groups_for_events
        )
        states = yield logcontext.make_deferred_yieldable(defer.gatherResults(
            [resolve(room_id, [e]) for e in event_ids],
            consumeErrors=True,
        ))
        states = dict(zip(event_ids, [s.state for s in states]))
        state_map = yield self.store.get_events(
            [e_id for ids in itervalues(states) for e_id in itervalues(ids)],
            get_prev_content=False
        )
        states = {
            key: {
                k: state_map[e_id]
                for k, e_id in iteritems(state_dict)
                if e_id in state_map
            } for key, state_dict in iteritems(states)
        }
        for e_id, _ in sorted_extremeties_tuple:
            likely_domains = get_domains_from_state(states[e_id])
            success = yield try_backfill([
                dom for dom, _ in likely_domains
                if dom not in tried_domains
            ])
            if success:
                defer.returnValue(True)
            tried_domains.update(dom for dom, _ in likely_domains)
        defer.returnValue(False)
    def do_invite_join(self, target_hosts, room_id, joinee, content):
        """ Attempts to join the `joinee` to the room `room_id` via the
        server `target_host`.
        This first triggers a /make_join/ request that returns a partial
        event that we can fill out and sign. This is then sent to the
        remote server via /send_join/ which responds with the state at that
        event and the auth_chains.
        We suspend processing of any received events from this room until we
        have finished processing the join.
        """
        logger.debug("Joining %s to %s", joinee, room_id)
        origin, event = yield self._make_and_verify_event(
            target_hosts,
            room_id,
            joinee,
            "join",
            content,
            params={
                "ver": KNOWN_ROOM_VERSIONS,
            },
        )
        assert (room_id not in self.room_queues)
        self.room_queues[room_id] = []
        yield self._clean_room_for_join(room_id)
        handled_events = set()
        try:
            event = self._sign_event(event)
            try:
                target_hosts.remove(origin)
                target_hosts.insert(0, origin)
            except ValueError:
                pass
            ret = yield self.federation_client.send_join(target_hosts, event)
            origin = ret["origin"]
            state = ret["state"]
            auth_chain = ret["auth_chain"]
            auth_chain.sort(key=lambda e: e.depth)
            handled_events.update([s.event_id for s in state])
            handled_events.update([a.event_id for a in auth_chain])
            handled_events.add(event.event_id)
            logger.debug("do_invite_join auth_chain: %s", auth_chain)
            logger.debug("do_invite_join state: %s", state)
            logger.debug("do_invite_join event: %s", event)
            try:
                yield self.store.store_room(
                    room_id=room_id,
                    room_creator_user_id="",
                    is_public=False
                )
            except Exception:
                pass
            yield self._persist_auth_tree(
                origin, auth_chain, state, event
            )
            logger.debug("Finished joining %s to %s", joinee, room_id)
        finally:
            room_queue = self.room_queues[room_id]
            del self.room_queues[room_id]
            logcontext.run_in_background(self._handle_queued_pdus, room_queue)
        defer.returnValue(True)
