            result = self.context.getString(length)
            return self.context.getStringForBytes(result)
        if length == 0:
            return ''
        result = self.stream.read(length)
        self.context.addString(result)
        return self.context.getStringForBytes(result)
    def readDate(self):
        """
        Read date from the stream.
        The timezone is ignored as the date is always in UTC.
        """
        ref = self.readInteger(False)
        if ref & REFERENCE_BIT == 0:
            return self.context.getObject(ref >> 1)
        ms = self.stream.read_double()
        result = util.get_datetime(ms / 1000.0)
        if self.timezone_offset is not None:
            result += self.timezone_offset
        self.context.addObject(result)
        return result
    def readArray(self):
        """
        Reads an array from the stream.
        @warning: There is a very specific problem with AMF3 where the first
        three bytes of an encoded empty C{dict} will mirror that of an encoded
        C{{'': 1, '2': 2}}
        """
        size = self.readInteger(False)
        if size & REFERENCE_BIT == 0:
            return self.context.getObject(size >> 1)
        size >>= 1
        key = self.readBytes()
        if key == '':
            result = []
            self.context.addObject(result)
            for i in xrange(size):
                result.append(self.readElement())
            return result
        result = pyamf.MixedArray()
        self.context.addObject(result)
        while key:
            result[key] = self.readElement()
            key = self.readBytes()
        for i in xrange(size):
            el = self.readElement()
            result[i] = el
        return result
    def _getClassDefinition(self, ref):
        """
        Reads class definition from the stream.
        """
        is_ref = ref & REFERENCE_BIT == 0
        ref >>= 1
        if is_ref:
            class_def = self.context.getClassByReference(ref)
            return class_def
        name = self.readBytes()
        alias = None
        if name == '':
            name = pyamf.ASObject
        try:
            alias = pyamf.get_class_alias(name)
        except pyamf.UnknownClassAlias:
            if self.strict:
                raise
            alias = pyamf.TypedObjectClassAlias(name)
        class_def = ClassDefinition(alias)
        class_def.encoding = ref & 0x03
        class_def.attr_len = ref >> 2
        class_def.static_properties = []
        if class_def.attr_len > 0:
            for i in xrange(class_def.attr_len):
                key = self.readBytes()
                class_def.static_properties.append(key)
        self.context.addClass(class_def, alias.klass)
        return class_def
    def _readStatic(self, class_def, obj):
        for attr in class_def.static_properties:
            obj[attr] = self.readElement()
    def _readDynamic(self, class_def, obj):
        attr = self.readBytes()
        while attr:
            obj[attr] = self.readElement()
            attr = self.readBytes()
    def readObject(self):
        """
        Reads an object from the stream.
        @raise ReferenceError: Unknown reference found.
        @raise DecodeError: Unknown object encoding detected.
        """
        ref = self.readInteger(False)
        if ref & REFERENCE_BIT == 0:
            obj = self.context.getObject(ref >> 1)
            if obj is None:
                raise pyamf.ReferenceError(
                    'Unknown reference %d' % (ref >> 1,)
                )
            if self.use_proxies is True:
                obj = self.readProxy(obj)
            return obj
        ref >>= 1
        class_def = self._getClassDefinition(ref)
        alias = class_def.alias
        obj = alias.createInstance(codec=self)
        obj_attrs = dict()
        self.context.addObject(obj)
        if class_def.encoding in (
                ObjectEncoding.EXTERNAL,
                ObjectEncoding.PROXY):
            obj.__readamf__(DataInput(self))
            if self.use_proxies is True:
                obj = self.readProxy(obj)
            return obj
        elif class_def.encoding == ObjectEncoding.DYNAMIC:
            self._readStatic(class_def, obj_attrs)
            self._readDynamic(class_def, obj_attrs)
        elif class_def.encoding == ObjectEncoding.STATIC:
            self._readStatic(class_def, obj_attrs)
        else:
            raise pyamf.DecodeError("Unknown object encoding")
        alias.applyAttributes(obj, obj_attrs, codec=self)
        if self.use_proxies is True:
            obj = self.readProxy(obj)
        return obj
    def readXML(self):
        """
        Reads an xml object from the stream.
        @return: An etree interface compatible object
        @see: L{xml.set_default_interface}
        """
        ref = self.readInteger(False)
        if ref & REFERENCE_BIT == 0:
            return self.context.getObject(ref >> 1)
        xmlstring = self.stream.read(ref >> 1)
        x = xml.fromstring(
            xmlstring,
            forbid_dtd=self.context.forbid_dtd,
            forbid_entities=self.context.forbid_entities,
        )
        self.context.addObject(x)
        return x
    def readXMLString(self):
        """
        Reads a string from the data stream and converts it into
        an XML Tree.
        @see: L{readXML}
        """
        return self.readXML()
    def readByteArray(self):
        """
        Reads a string of data from the stream.
        Detects if the L{ByteArray} was compressed using C{zlib}.
        @see: L{ByteArray}
        @note: This is not supported in ActionScript 1.0 and 2.0.
        """
        ref = self.readInteger(False)
        if ref & REFERENCE_BIT == 0:
            return self.context.getObject(ref >> 1)
        buffer = self.stream.read(ref >> 1)
        compressed = False
        if buffer[0:2] == ByteArray._zlib_header:
            try:
                buffer = zlib.decompress(buffer)
                compressed = True
            except zlib.error:
                pass
        obj = ByteArray(buffer)
        obj.compressed = compressed
        self.context.addObject(obj)
        return obj
    def serialiseBytes(self, b):
        if len(b) == 0:
            self.stream.write_uchar(REFERENCE_BIT)
            return
        if self.string_references:
            ref = self.context.getStringReference(b)
            if ref != -1:
                self._writeInteger(ref << 1)
                return
            self.context.addString(b)
        self._writeInteger((len(b) << 1) | REFERENCE_BIT)
        self.stream.write(b)
    def writeDate(self, n):
        """
        Writes a C{datetime} instance to the stream.
        Does not support C{datetime.time} instances because AMF3 has
        no way to encode time objects, so please use C{datetime.datetime}
        instead.
        @type n: L{datetime}
        @param n: The C{Date} data to be encoded to the AMF3 data stream.
        @raise EncodeError: A datetime.time instance was found
        """
        if isinstance(n, datetime.time):
            raise pyamf.EncodeError(
                'A datetime.time instance was found but AMF3 has no way to '
                'encode time objects. Please use datetime.datetime instead '
                '(got:%r)' % (n,)
            )
        self.stream.write(TYPE_DATE)
        ref = self.context.getObjectReference(n)
        if ref != -1:
            self._writeInteger(ref << 1)
            return
        self.context.addObject(n)
        self.stream.write_uchar(REFERENCE_BIT)
        if self.timezone_offset is not None:
            n -= self.timezone_offset
        ms = util.get_timestamp(n)
        self.stream.write_double(ms * 1000.0)
    def writeList(self, n, is_proxy=False):
        """
        Writes a C{tuple}, C{set} or C{list} to the stream.
        @type n: One of C{__builtin__.tuple}, C{__builtin__.set}
            or C{__builtin__.list}
        @param n: The C{list} data to be encoded to the AMF3 data stream.
        """
        if self.use_proxies and not is_proxy:
            self.writeProxy(n)
            return
        self.stream.write(TYPE_ARRAY)
        ref = self.context.getObjectReference(n)
        if ref != -1:
            self._writeInteger(ref << 1)
            return
        self.context.addObject(n)
        self._writeInteger((len(n) << 1) | REFERENCE_BIT)
        self.stream.write('\x01')
        [self.writeElement(x) for x in n]
    def writeDict(self, n):
        """
        Writes a C{dict} to the stream.
        @type n: C{__builtin__.dict}
        @param n: The C{dict} data to be encoded to the AMF3 data stream.
        @raise ValueError: Non C{int}/C{str} key value found in the C{dict}
        @raise EncodeError: C{dict} contains empty string keys.
        """
        if '' in n:
            raise pyamf.EncodeError("dicts cannot contain empty string keys")
        if self.use_proxies:
            self.writeProxy(n)
            return
        self.stream.write(TYPE_ARRAY)
        ref = self.context.getObjectReference(n)
        if ref != -1:
            self._writeInteger(ref << 1)
            return
        self.context.addObject(n)
        keys = n.keys()
        int_keys = []
        str_keys = []
        for x in keys:
            if isinstance(x, python.int_types):
                int_keys.append(x)
            elif isinstance(x, python.str_types):
                str_keys.append(x)
            else:
                raise ValueError("Non int/str key value found in dict")
        l = len(int_keys)
        for x in int_keys:
            if l < x <= 0:
                str_keys.append(x)
                del int_keys[int_keys.index(x)]
        int_keys.sort()
        if len(int_keys) > 0 and int_keys[0] != 0:
            for x in int_keys:
                str_keys.append(str(x))
                del int_keys[int_keys.index(x)]
        self._writeInteger(len(int_keys) << 1 | REFERENCE_BIT)
        for x in str_keys:
            self.serialiseString(x)
            self.writeElement(n[x])
        self.stream.write_uchar(0x01)
        for k in int_keys:
            self.writeElement(n[k])
    def writeObject(self, obj, is_proxy=False):
        """
        Writes an object to the stream.
        """
        if self.use_proxies and not is_proxy:
            self.writeProxy(obj)
            return
        self.stream.write(TYPE_OBJECT)
        ref = self.context.getObjectReference(obj)
        if ref != -1:
            self._writeInteger(ref << 1)
            return
        self.context.addObject(obj)
        kls = obj.__class__
        definition = self.context.getClass(kls)
        alias = None
        class_ref = False
        if definition:
            class_ref = True
            alias = definition.alias
        else:
            alias = self.context.getClassAlias(kls)
            definition = ClassDefinition(alias)
            self.context.addClass(definition, alias.klass)
        if class_ref:
            self.stream.write(definition.reference)
        else:
            ref = 0
            if definition.encoding != ObjectEncoding.EXTERNAL:
                ref += definition.attr_len << 4
            final_reference = encode_int(
                ref |
                definition.encoding << 2 |
                REFERENCE_BIT << 1 |
                REFERENCE_BIT
            )
            self.stream.write(final_reference)
            definition.reference = encode_int(
                definition.reference << 2 | REFERENCE_BIT)
            if alias.anonymous:
                self.stream.write('\x01')
            else:
                self.serialiseString(alias.alias)
        if alias.external:
            obj.__writeamf__(DataOutput(self))
            return
        attrs = alias.getEncodableAttributes(obj, codec=self)
        if alias.static_attrs:
            if not class_ref:
                [self.serialiseString(attr) for attr in alias.static_attrs]
            for attr in alias.static_attrs:
                value = attrs.pop(attr)
                self.writeElement(value)
            if definition.encoding == ObjectEncoding.STATIC:
                return
        if definition.encoding == ObjectEncoding.DYNAMIC:
            if attrs:
                for attr, value in attrs.iteritems():
                    if type(attr) in python.int_types:
                        attr = str(attr)
                    self.serialiseString(attr)
                    self.writeElement(value)
            self.stream.write('\x01')
    def writeByteArray(self, n):
        """
        Writes a L{ByteArray} to the data stream.
        @param n: The L{ByteArray} data to be encoded to the AMF3 data stream.
        @type n: L{ByteArray}
        """
        self.stream.write(TYPE_BYTEARRAY)
        ref = self.context.getObjectReference(n)
        if ref != -1:
            self._writeInteger(ref << 1)
            return
        self.context.addObject(n)
        buf = str(n)
        l = len(buf)
        self._writeInteger(l << 1 | REFERENCE_BIT)
        self.stream.write(buf)
ET = None
def set_default_interface(etree):
    """
    Sets the default interface that PyAMF will use to deal with XML entities
    (both objects and blobs).
    """
    global types, ET, modules
    t = _get_etree_type(etree)
    _types = set(types or [])
    _types.update([t])
    types = tuple(_types)
    modules[t] = etree
    old, ET = ET, etree
    return old
def _bootstrap():
    global types, modules, ET
    if types is None:
        types, modules = find_libs()
    if ET is None:
        try:
            etree = modules[types[0]]
        except IndexError:
            _no_et()
        set_default_interface(etree)
def fromstring(*args, **kwargs):
    """
    Helper func to provide easy access to the (possibly) moving target that is
    C{ET}.
    """
    global ET
    _bootstrap()
    kwargs.setdefault('forbid_dtd', True)
    kwargs.setdefault('forbid_entities', True)
    return ET.fromstring(*args, **kwargs)
can_compile_extensions = not jython
def get_install_requirements():
    """
    Returns a list of dependencies for PyAMF to function correctly on the
    target platform.
    """
    install_requires = ['defusedxml']
    if sys.version_info < (2, 5):
        install_requires.extend(["elementtree>=1.2.6", "uuid>=1.30"])
    if 'dev' in get_version():
        if can_compile_extensions:
            install_requires.extend(['Cython>=0.13'])
    return install_requires
def get_extensions():
    """
    Return a list of Extension instances that can be compiled.
    """
    if not can_compile_extensions:
        print(80 * '*')
        print('WARNING:')
        print(
            '\tAn optional code optimization (C extension) could not be '
            'compiled.\n\n'
        )
        print('\tOptimizations for this package will not be available!\n\n')
        print('Compiling extensions is not supported on %r' % (sys.platform,))
        print(80 * '*')
        return []
    extensions = []
    for p in recursive_glob('.', '*.pyx'):
        mod_name = os.path.splitext(p)[0].replace(os.path.sep, '.')
        e = make_extension(mod_name)
        if e:
            extensions.append(e)
    return extensions

class SevenZipFile(contextlib.AbstractContextManager):
        self,
    def __enter__(self):
        return self
    def _fpclose(self) -> None:
        assert self._fileRefCnt > 0
        self._fileRefCnt -= 1
        if not self._fileRefCnt and not self._filePassed:
            self.fp.close()
    def _real_get_contents(self, password) -> None:
        if not self._check_7zfile(self.fp):
            raise Bad7zFile("not a 7z file")
        self.sig_header = SignatureHeader.retrieve(self.fp)
        self.afterheader: int = self.fp.tell()
        self.fp.seek(self.sig_header.nextheaderofs, os.SEEK_CUR)
        buffer = io.BytesIO(self.fp.read(self.sig_header.nextheadersize))
        if self.sig_header.nextheadercrc != calculate_crc32(buffer.getvalue()):
            raise Bad7zFile("invalid header data")
        header = Header.retrieve(self.fp, buffer, self.afterheader, password)
        if header is None:
            return
        header._initilized = True
        self.header = header
        header.size += 32 + self.sig_header.nextheadersize
        buffer.close()
        self.files = ArchiveFileList()
        if getattr(self.header, "files_info", None) is None:
            return
        if hasattr(self.header, "main_streams") and self.header.main_streams is not None:
            folders = self.header.main_streams.unpackinfo.folders
            for folder in folders:
                folder.password = password
            packinfo = self.header.main_streams.packinfo
            packsizes = packinfo.packsizes
            subinfo = self.header.main_streams.substreamsinfo
            if subinfo is not None and subinfo.unpacksizes is not None:
                unpacksizes = subinfo.unpacksizes
            else:
                unpacksizes = [x.unpacksizes[-1] for x in folders]
        else:
            subinfo = None
            folders = None
            packinfo = None
            packsizes = []
            unpacksizes = [0]
        pstat = self.ParseStatus()
        pstat.src_pos = self.afterheader
        file_in_solid = 0
        for file_id, file_info in enumerate(self.header.files_info.files):
            if not file_info["emptystream"] and folders is not None:
                folder = folders[pstat.folder]
                numinstreams = max([coder.get("numinstreams", 1) for coder in folder.coders])
                (maxsize, compressed, uncompressed, packsize, solid,) = self._get_fileinfo_sizes(
                    pstat,
                    subinfo,
                    packinfo,
                    folder,
                    packsizes,
                    unpacksizes,
                    file_in_solid,
                    numinstreams,
                )
                pstat.input += 1
                folder.solid = solid
                file_info["folder"] = folder
                file_info["maxsize"] = maxsize
                file_info["compressed"] = compressed
                file_info["uncompressed"] = uncompressed
                file_info["packsizes"] = packsize
                if subinfo.digestsdefined[pstat.outstreams]:
                    file_info["digest"] = subinfo.digests[pstat.outstreams]
                if folder is None:
                    pstat.src_pos += file_info["compressed"]
                else:
                    if folder.solid:
                        file_in_solid += 1
                    pstat.outstreams += 1
                    if folder.files is None:
                        folder.files = ArchiveFileList(offset=file_id)
                    folder.files.append(file_info)
                    if pstat.input >= subinfo.num_unpackstreams_folders[pstat.folder]:
                        file_in_solid = 0
                        pstat.src_pos += sum(packinfo.packsizes[pstat.stream : pstat.stream + numinstreams])
                        pstat.folder += 1
                        pstat.stream += numinstreams
                        pstat.input = 0
            else:
                file_info["folder"] = None
                file_info["maxsize"] = 0
                file_info["compressed"] = 0
                file_info["uncompressed"] = 0
                file_info["packsizes"] = [0]
            if "filename" not in file_info:
                try:
                    basefilename = self.filename
                except AttributeError:
                    file_info["filename"] = "contents"
                else:
                    if basefilename is not None:
                        fn, ext = os.path.splitext(os.path.basename(basefilename))
                        file_info["filename"] = fn
                    else:
                        file_info["filename"] = "contents"
            self.files.append(file_info)
        if not self.password_protected and self.header.main_streams is not None:
            self.password_protected = any(
                [SupportedMethods.needs_password(folder.coders) for folder in self.header.main_streams.unpackinfo.folders]
            )
    def _extract(
        self,
        path: Optional[Any] = None,
        targets: Optional[List[str]] = None,
        return_dict: bool = False,
        callback: Optional[ExtractCallback] = None,
    ) -> Optional[Dict[str, IO[Any]]]:
        if callback is None:
            pass
        elif isinstance(callback, ExtractCallback):
            self.reporterd = Thread(target=self.reporter, args=(callback,), daemon=True)
            self.reporterd.start()
        else:
            raise ValueError("Callback specified is not an instance of subclass of py7zr.callbacks.ExtractCallback class")
        target_files: List[Tuple[pathlib.Path, Dict[str, Any]]] = []
        target_dirs: List[pathlib.Path] = []
        if path is not None:
            if isinstance(path, str):
                path = pathlib.Path(path)
            try:
                if not path.exists():
                    path.mkdir(parents=True)
                else:
                    pass
            except OSError as e:
                if e.errno == errno.EEXIST and path.is_dir():
                    pass
                else:
                    raise e
        fnames: List[str] = []
        self.q.put(("pre", None, None))
        for f in self.files:
            if f.filename not in fnames:
                outname = f.filename
            else:
                i = 0
                while True:
                    outname = f.filename + "_%d" % i
                    if outname not in fnames:
                        break
                    i += 1
            fnames.append(outname)
            if path is None:
                try:
                    pathlib.Path(os.getcwd()).joinpath(remove_relative_path_marker(outname)).relative_to(os.getcwd())
                except ValueError:
                    raise Bad7zFile
                outfilename = pathlib.Path(remove_relative_path_marker(outname))
            else:
                outfilename = path.joinpath(remove_relative_path_marker(outname))
                try:
                    outfilename.relative_to(path)
                except ValueError:
                    raise Bad7zFile
            if is_windows_native_python() and outfilename.is_absolute() and not is_windows_unc_path(outfilename):
                outfilename = pathlib.WindowsPath("\\\\?\\" + str(outfilename))
            if targets is not None and f.filename not in targets:
                self.worker.register_filelike(f.id, None)
                continue
            if return_dict:
                if f.is_directory or f.is_socket:
                    pass
                else:
                    fname = outfilename.as_posix()
                    _buf = io.BytesIO()
                    self._dict[fname] = _buf
                    self.worker.register_filelike(f.id, MemIO(_buf))
            elif f.is_directory:
                if not outfilename.exists():
                    target_dirs.append(outfilename)
                    target_files.append((outfilename, f.file_properties()))
                else:
                    pass
            elif f.is_socket:
                pass
            elif f.is_symlink or f.is_junction:
                self.worker.register_filelike(f.id, outfilename)
            else:
                self.worker.register_filelike(f.id, outfilename)
                target_files.append((outfilename, f.file_properties()))
        for target_dir in sorted(target_dirs):
            try:
                target_dir.mkdir(parents=True)
            except FileExistsError:
                if target_dir.is_dir():
                    pass
                elif target_dir.is_file():
                    raise DecompressionError("Directory {} is existed as a normal file.".format(str(target_dir)))
                else:
                    raise DecompressionError("Directory {} making fails on unknown condition.".format(str(target_dir)))
        if callback is not None:
            self.worker.extract(
                self.fp,
                parallel=(not self.password_protected and not self._filePassed),
                q=self.q,
            )
        else:
            self.worker.extract(
                self.fp,
                parallel=(not self.password_protected and not self._filePassed),
            )
        self.q.put(("post", None, None))
        if return_dict:
            return self._dict
        for outfilename, properties in target_files:
            lastmodified = None
            try:
                lastmodified = ArchiveTimestamp(properties["lastwritetime"]).totimestamp()
            except KeyError:
                pass
            if lastmodified is not None:
                os.utime(str(outfilename), times=(lastmodified, lastmodified))
            if os.name == "posix":
                st_mode = properties["posix_mode"]
                if st_mode is not None:
                    outfilename.chmod(st_mode)
                    continue
            if properties["readonly"] and not properties["is_directory"]:
                ro_mask = 0o777 ^ (stat.S_IWRITE | stat.S_IWGRP | stat.S_IWOTH)
                outfilename.chmod(outfilename.stat().st_mode & ro_mask)
        return None
    def _prepare_append(self, filters, password):
        if password is not None and filters is None:
            filters = DEFAULT_FILTERS.ENCRYPTED_ARCHIVE_FILTER
        elif filters is None:
            filters = DEFAULT_FILTERS.ARCHIVE_FILTER
        else:
            for f in filters:
                if f["id"] == FILTER_DEFLATE64:
                    raise UnsupportedCompressionMethodError(filters, "Compression with deflate64 is not supported.")
        self.header.filters = filters
        self.header.password = password
        if self.header.main_streams is not None:
            pos = self.afterheader + self.header.main_streams.packinfo.packpositions[-1]
        else:
            pos = self.afterheader
        self.fp.seek(pos)
        self.worker = Worker(self.files, pos, self.header, self.mp)
        def __init__(self, src_pos=0):
            self.src_pos = src_pos
            self.folder = 0
            self.outstreams = 0
            self.input = 0
            self.stream = 0
    def _get_fileinfo_sizes(
        self,
        pstat,
        subinfo,
        packinfo,
        folder,
        packsizes,
        unpacksizes,
        file_in_solid,
        numinstreams,
    ):
        if pstat.input == 0:
            folder.solid = subinfo.num_unpackstreams_folders[pstat.folder] > 1
        maxsize = (folder.solid and packinfo.packsizes[pstat.stream]) or None
        uncompressed = unpacksizes[pstat.outstreams]
        if file_in_solid > 0:
            compressed = None
        elif pstat.stream < len(packsizes):
            compressed = packsizes[pstat.stream]
        else:
            compressed = uncompressed
        packsize = packsizes[pstat.stream : pstat.stream + numinstreams]
        return maxsize, compressed, uncompressed, packsize, folder.solid
    def _check_7zfile(fp: Union[BinaryIO, io.BufferedReader, io.IOBase]) -> bool:
        result = MAGIC_7Z == fp.read(len(MAGIC_7Z))[: len(MAGIC_7Z)]
        fp.seek(-len(MAGIC_7Z), 1)
        return result
    def archiveinfo(self) -> ArchiveInfo:
        total_uncompressed = functools.reduce(lambda x, y: x + y, [f.uncompressed for f in self.files])
        if isinstance(self.fp, multivolumefile.MultiVolume):
            fname = self.fp.name
            fstat = self.fp.stat()
        else:
            fname = self.filename
            assert fname is not None
            fstat = os.stat(fname)
        return ArchiveInfo(
            fname,
            fstat,
            self.header.size,
            self._get_method_names(),
            self._is_solid(),
            len(self.header.main_streams.unpackinfo.folders),
            total_uncompressed,
        )
    def writed(self, targets: Dict[str, IO[Any]]) -> None:
        for target, input in targets.items():
            self.writef(input, target)
    def writef(self, bio: IO[Any], arcname: str):
        if isinstance(bio, io.BytesIO):
            size = bio.getbuffer().nbytes
        elif isinstance(bio, io.TextIOBase):
            raise ValueError("Unsupported file object type: please open file with Binary mode.")
        elif isinstance(bio, io.BufferedIOBase):
            current = bio.tell()
            bio.seek(0, os.SEEK_END)
            last = bio.tell()
            bio.seek(current, os.SEEK_SET)
            size = last - current
        else:
            raise ValueError("Wrong argument passed for argument bio.")
        if size > 0:
            folder = self.header.initialize()
            file_info = self._make_file_info_from_name(bio, size, arcname)
            self.header.files_info.files.append(file_info)
            self.header.files_info.emptyfiles.append(file_info["emptystream"])
            self.files.append(file_info)
            self.worker.archive(self.fp, self.files, folder, deref=False)
        else:
            file_info = self._make_file_info_from_name(bio, size, arcname)
            self.header.files_info.files.append(file_info)
            self.header.files_info.emptyfiles.append(file_info["emptystream"])
            self.files.append(file_info)
    def writestr(self, data: Union[str, bytes, bytearray, memoryview], arcname: str):
        if not isinstance(arcname, str):
            raise ValueError("Unsupported arcname")
        if isinstance(data, str):
            self.writef(io.BytesIO(data.encode("UTF-8")), arcname)
        elif isinstance(data, bytes) or isinstance(data, bytearray) or isinstance(data, memoryview):
            self.writef(io.BytesIO(data), arcname)
        else:
            raise ValueError("Unsupported data type.")
class Worker:
    def extract(self, fp: BinaryIO, parallel: bool, skip_notarget=True, q=None) -> None:
        """Extract worker method to handle 7zip folder and decompress each files."""
        if hasattr(self.header, "main_streams") and self.header.main_streams is not None:
            src_end = self.src_start + self.header.main_streams.packinfo.packpositions[-1]
            numfolders = self.header.main_streams.unpackinfo.numfolders
            if numfolders == 1:
                self.extract_single(
                    fp,
                    self.files,
                    self.src_start,
                    src_end,
                    q,
                    skip_notarget=skip_notarget,
                )
            else:
                folders = self.header.main_streams.unpackinfo.folders
                positions = self.header.main_streams.packinfo.packpositions
                empty_files = [f for f in self.files if f.emptystream]
                if not parallel:
                    self.extract_single(fp, empty_files, 0, 0, q)
                    for i in range(numfolders):
                        if skip_notarget:
                            if not any([self.target_filepath.get(f.id, None) for f in folders[i].files]):
                                continue
                        self.extract_single(
                            fp,
                            folders[i].files,
                            self.src_start + positions[i],
                            self.src_start + positions[i + 1],
                            q,
                            skip_notarget=skip_notarget,
                        )
                else:
                    if getattr(fp, "name", None) is None:
                        raise InternalError("Caught unknown variable status error")
                    filename: str = getattr(fp, "name", "")
                    self.extract_single(open(filename, "rb"), empty_files, 0, 0, q)
                    concurrent_tasks = []
                    exc_q: queue.Queue = queue.Queue()
                    for i in range(numfolders):
                        if skip_notarget:
                            if not any([self.target_filepath.get(f.id, None) for f in folders[i].files]):
                                continue
                        p = self.concurrent(
                            target=self.extract_single,
                            args=(
                                filename,
                                folders[i].files,
                                self.src_start + positions[i],
                                self.src_start + positions[i + 1],
                                q,
                                exc_q,
                                skip_notarget,
                            ),
                        )
                        p.start()
                        concurrent_tasks.append(p)
                    for p in concurrent_tasks:
                        p.join()
                    if exc_q.empty():
                        pass
                    else:
                        exc_info = exc_q.get()
                        raise exc_info[1].with_traceback(exc_info[2])
        else:
            empty_files = [f for f in self.files if f.emptystream]
            self.extract_single(fp, empty_files, 0, 0, q)
    def _extract_single(
        self,
        fp: BinaryIO,
        files,
        src_end: int,
        q: Optional[queue.Queue],
        skip_notarget=True,
    ) -> None:
        """
        Single thread extractor that takes file lists in single 7zip folder.
        this may raise exception.
        """
        just_check: List[ArchiveFile] = []
        for f in files:
            if q is not None:
                q.put(
                    (
                        "s",
                        str(f.filename),
                        str(f.compressed) if f.compressed is not None else "0",
                    )
                )
            fileish = self.target_filepath.get(f.id, None)
            if fileish is None:
                if not f.emptystream:
                    just_check.append(f)
            else:
                self._check(fp, just_check, src_end)
                just_check = []
                fileish.parent.mkdir(parents=True, exist_ok=True)
                if not f.emptystream:
                    if f.is_junction and not isinstance(fileish, MemIO) and sys.platform == "win32":
                        with io.BytesIO() as ofp:
                            self.decompress(fp, f.folder, ofp, f.uncompressed, f.compressed, src_end)
                            dst: str = ofp.read().decode("utf-8")
                            if fileish.exists():
                                fileish.unlink()
                            if sys.platform == "win32":
                                _winapi.CreateJunction(str(fileish), dst)
                    elif f.is_symlink and not isinstance(fileish, MemIO):
                        with io.BytesIO() as omfp:
                            self.decompress(fp, f.folder, omfp, f.uncompressed, f.compressed, src_end)
                            omfp.seek(0)
                            sym_target = pathlib.Path(omfp.read().decode("utf-8"))
                            if fileish.exists():
                                fileish.unlink()
                            fileish.symlink_to(sym_target)
                    else:
                        with fileish.open(mode="wb") as obfp:
                            crc32 = self.decompress(fp, f.folder, obfp, f.uncompressed, f.compressed, src_end)
                            obfp.seek(0)
                            if f.crc32 is not None and crc32 != f.crc32:
                                raise CrcError(crc32, f.crc32, f.filename)
                else:
                    if not isinstance(fileish, MemIO):
                        fileish.touch()
                    else:
                        with fileish.open() as ofp:
                            pass
            if q is not None:
                q.put(("e", str(f.filename), str(f.uncompressed)))
        if not skip_notarget:
            self._check(fp, just_check, src_end)
    def _check(self, fp, check_target, src_end):
        """
        delayed execution of crc check.
        """
        for f in check_target:
            with NullIO() as ofp:
                crc32 = self.decompress(fp, f.folder, ofp, f.uncompressed, f.compressed, src_end)
            if f.crc32 is not None and crc32 != f.crc32:
                raise CrcError(crc32, f.crc32, f.filename)
    def decompress(
        self,
        fp: BinaryIO,
        folder,
        fq: IO[Any],
        size: int,
        compressed_size: Optional[int],
        src_end: int,
    ) -> int:
        """
        decompressor wrapper called from extract method.
        :parameter fp: archive source file pointer
        :parameter folder: Folder object that have decompressor object.
        :parameter fq: output file pathlib.Path
        :parameter size: uncompressed size of target file.
        :parameter compressed_size: compressed size of target file.
        :parameter src_end: end position of the folder
        :returns None
        """
        assert folder is not None
        out_remaining = size
        max_block_size = get_memory_limit()
        crc32 = 0
        decompressor = folder.get_decompressor(compressed_size)
        while out_remaining > 0:
            tmp = decompressor.decompress(fp, min(out_remaining, max_block_size))
            if len(tmp) > 0:
                out_remaining -= len(tmp)
                fq.write(tmp)
                crc32 = calculate_crc32(tmp, crc32)
            if out_remaining <= 0:
                break
        if fp.tell() >= src_end:
            if decompressor.crc is not None and not decompressor.check_crc():
                raise CrcError(decompressor.crc, decompressor.digest, None)
        return crc32
    def _find_link_target(self, target):
        """
        Find the target member of a symlink or hardlink member in the archive.
        """
        targetname: str = target.as_posix()
        linkname = readlink(targetname)
        if linkname.startswith("\\\\?\\"):
            linkname = linkname[4:]
        linkname: str = pathlib.Path(linkname).as_posix()
        member = None
        for j in range(len(self.files)):
            if linkname == self.files[j].origin.as_posix():
                member = os.path.relpath(linkname, os.path.dirname(targetname))
                break
        if member is None:
            member = linkname
        return member
