class AuthorConverter(Converter):
    def xmp_from_docinfo(docinfo_val):
        return [docinfo_val]
    def docinfo_from_xmp(xmp_val):
        if isinstance(xmp_val, str):
            return xmp_val
        elif xmp_val is None or xmp_val == [None]:
            return None
        else:
            return '; '.join(xmp_val)
class DateConverter(Converter):
    def xmp_from_docinfo(docinfo_val):
        if docinfo_val == '':
