        should_loop = src.encoding == Encoding.ABI and src.typ.value_type.abi_type.is_dynamic()
        should_loop |= needs_clamp(src.typ.value_type, src.encoding)
        should_loop |= src.typ.value_type.abi_type.is_dynamic()
