            return
        arith = IRnode.from_list(arith, typ=new_typ)
        p = [
            "with",
            "l",
            left,
            [
                "with",
                "r",
                right,
                clamp_basetype(arith),
            ],
        ]
        return IRnode.from_list(p, typ=new_typ)
            ith_element_ptr = get_element_ptr(right, i, array_bounds_check=False)
            loop_body = [
