def _unpack_returndata(buf, contract_sig, skip_contract_check, context):
    return_t = contract_sig.return_type
    if return_t is None:
        return ["pass"], 0, 0
    return_t = calculate_type_for_external_return(return_t)
    should_unwrap_abi_tuple = return_t != contract_sig.return_type
    abi_return_t = return_t.abi_type
    min_return_size = abi_return_t.min_size()
    max_return_size = abi_return_t.size_bound()
    assert 0 < min_return_size <= max_return_size
    ret_ofst = buf
    ret_len = max_return_size
    ret = []
    if not skip_contract_check:
        ret += [["assert", ["gt", "returndatasize", min_return_size - 1]]]
    buf = IRnode(buf, typ=return_t, encoding=_returndata_encoding(contract_sig), location=MEMORY)
    if should_unwrap_abi_tuple:
        buf = get_element_ptr(buf, 0, array_bounds_check=False)
    ret += [buf]
    return ret, ret_ofst, ret_len
class RawCall(_SimpleBuiltinFunction):
    def build_IR(self, expr, args, kwargs, context):
        to, data = args
        gas, value, outsize, delegate_call, static_call, revert_on_failure = (
            kwargs["gas"],
            kwargs["value"],
            kwargs["max_outsize"],
            kwargs["is_delegate_call"],
            kwargs["is_static_call"],
            kwargs["revert_on_failure"],
        )
        for key in ("is_delegate_call", "is_static_call", "revert_on_failure"):
            if kwargs[key].typ.is_literal is False:
                raise TypeMismatch(
                    f"The `{key}` parameter must be a static/literal boolean value", expr
                )
        revert_on_failure = revert_on_failure.value == 1
        static_call = static_call.value == 1
        delegate_call = delegate_call.value == 1
        if delegate_call and static_call:
            raise ArgumentException(
                "Call may use one of `is_delegate_call` or `is_static_call`, not both", expr
            )
        if not static_call and context.is_constant():
            raise StateAccessViolation(
                f"Cannot make modifying calls from {context.pp_constancy()},"
                " use `is_static_call=True` to perform this action",
                expr,
            )
        eval_input_buf = ensure_in_memory(data, context)
        input_buf = eval_seq(eval_input_buf)
        output_node = IRnode.from_list(
            context.new_internal_variable(ByteArrayType(outsize)),
            typ=ByteArrayType(outsize),
            location=MEMORY,
        )
        bool_ty = BaseType("bool")
        if input_buf is None:
            call_ir = ["with", "arg_buf", eval_input_buf]
            input_buf = IRnode.from_list("arg_buf")
        else:
            call_ir = ["seq", eval_input_buf]
        common_call_args = [
            add_ofst(input_buf, 32),
            ["mload", input_buf],
            add_ofst(output_node, 32) if outsize else 0,
            outsize,
        ]
        if delegate_call:
            call_op = ["delegatecall", gas, to, *common_call_args]
        elif static_call:
            call_op = ["staticcall", gas, to, *common_call_args]
        else:
            call_op = ["call", gas, to, value, *common_call_args]
        call_ir += [call_op]
        if outsize:
            size = [
                "with",
                "_l",
                outsize,
                ["with", "_r", "returndatasize", ["if", ["gt", "_l", "_r"], "_r", "_l"]],
            ]
            store_output_size = [
                "with",
                "output_pos",
                output_node,
                ["seq", ["mstore", "output_pos", size], "output_pos"],
            ]
            bytes_ty = ByteArrayType(outsize)
            if revert_on_failure:
                typ = bytes_ty
                ret_ir = ["seq", check_external_call(call_ir), store_output_size]
            else:
                typ = TupleType([bool_ty, bytes_ty])
                ret_ir = [
                    "multi",
                    IRnode.from_list(call_ir, typ=bool_ty),
                    IRnode.from_list(store_output_size, typ=bytes_ty, location=MEMORY),
                ]
        else:
            if revert_on_failure:
                typ = None
                ret_ir = check_external_call(call_ir)
            else:
                typ = bool_ty
                ret_ir = call_ir
        return IRnode.from_list(ret_ir, typ=typ, location=MEMORY)
    def _assert_reason(self, test_expr, msg):
        if isinstance(msg, vy_ast.Name) and msg.id == "UNREACHABLE":
            return IRnode.from_list(["assert_unreachable", test_expr])
        try:
            tmp = self.context.constancy
            self.context.constancy = Constancy.Constant
            msg_ir = Expr(msg, self.context).ir_node
        finally:
            self.context.constancy = tmp
        def _get_last(ir):
            if len(ir.args) == 0:
                return ir.value
            return _get_last(ir.args[-1])
        if msg_ir.location != MEMORY:
            buf = self.context.new_internal_variable(msg_ir.typ)
            instantiate_msg = make_byte_array_copier(buf, msg_ir)
        else:
            buf = _get_last(msg_ir)
            if not isinstance(buf, int):
                raise CompilerPanic(f"invalid bytestring {buf}\n{self}")
            instantiate_msg = msg_ir
        method_id = util.abi_method_id("Error(string)")
        assert buf >= 36, "invalid buffer"
        _runtime_length = ["mload", buf]
        revert_seq = [
            "seq",
            instantiate_msg,
            zero_pad(buf),
            ["mstore", buf - 64, method_id],
            ["mstore", buf - 32, 0x20],
            ["revert", buf - 36, ["add", 4 + 32 + 32, ["ceil32", _runtime_length]]],
        ]
        if test_expr is not None:
            ir_node = ["if", ["iszero", test_expr], revert_seq]
        else:
            ir_node = revert_seq
        return IRnode.from_list(ir_node)
def bytes_data_ptr(ptr):
    if ptr.location is None:
        raise CompilerPanic("tried to modify non-pointer type")
    assert isinstance(ptr.typ, ByteArrayLike)
    return add_ofst(ptr, ptr.location.word_scale)
def ensure_in_memory(ir_var, context):
    """Ensure a variable is in memory. This is useful for functions
    which expect to operate on memory variables.
    """
    if ir_var.location == MEMORY:
        return ir_var
    typ = ir_var.typ
    buf = IRnode.from_list(context.new_internal_variable(typ), typ=typ, location=MEMORY)
    do_copy = make_setter(buf, ir_var)
    return IRnode.from_list(["seq", do_copy, buf], typ=typ, location=MEMORY)
MEMORY = AddrSpace("memory", 32, "mload", "mstore")

FILENAME = os.path.expanduser(config.get("auth", "htpasswd_filename"))
def is_authenticated(user, password):
    """Validate credentials.
    Iterate through htpasswd credential file until user matches, extract hash
    (encrypted password) and check hash against user-given password, using the
    method specified in the Radicale config.
    """
    with open(FILENAME) as f:
        for line in f:
            strippedline = line.strip()
            if strippedline:
                login, hash_value = strippedline.split(":")
                if login == user:
                    return _verifuncs[ENCRYPTION](hash_value, password)
    return False

class _ExpiringDict(dict):
    max_age = 0
    def __init__(self, max_age=0):
        self.max_age = max_age
        self.timestamps = {}
        self.values = {}
    def _check_age(self, key):
        """Check timestamp for a key"""
        if key not in self.values:
            return
        now = time.monotonic()
        timestamp = self.timestamps[key]
        if self.max_age > 0 and timestamp + self.max_age < now:
            self.values.pop(key)
            self.timestamps.pop(key)
    def __contains__(self, key):
        """dict check for `key in dict`"""
        self._check_age(key)
        return key in self.values
    def __getitem__(self, key):
        """Check age before returning value"""
        self._check_age(key)
        return self.values[key]
    def get(self, key, default=None):
        """dict-like get:"""
        try:
            return self[key]
        except KeyError:
            return default
