class Scanner:
    def run(self):
    def set_shares(self, share_type, files=None, streams=None, mtimes=None, wordindex=None):
        self.config.create_data_folder()
        storable_objects = [
            (files, "files"),
            (streams, "streams"),
            (mtimes, "mtimes"),
            (wordindex, "wordindex")
        ]
        for source, destination in storable_objects:
            if source is None:
                continue
            try:
                if share_type == "buddy":
                    destination = "buddy" + destination
                self.share_dbs[destination].close()
                self.share_dbs[destination] = shelve.open(os.path.join(self.config.data_dir, destination + ".db"),
                                                          flag='n', protocol=pickle.HIGHEST_PROTOCOL)
                self.share_dbs[destination].update(source)
            except Exception as error:
                self.queue.put((_("Can't save %(filename)s: %(error)s"),
                                {"filename": destination + ".db", "error": error}, None))
                return
    def rescan_dirs(self, share_type, mtimes=None, files=None, streams=None, rebuild=False):
        """
        Check for modified or new files via OS's last mtime on a directory,
        or, if rebuild is True, all directories
        """
        if share_type == "buddy":
            shared_folders = (x[1] for x in self.shared_buddy_folders)
            prefix = "buddy"
        else:
            shared_folders = (x[1] for x in self.shared_folders)
            prefix = ""
        new_files = {}
        new_streams = {}
        new_mtimes = {}
        if files is not None:
            new_files = {**files, **new_files}
        if streams is not None:
            new_streams = {**streams, **new_streams}
        if mtimes is not None:
            new_mtimes = {**mtimes, **new_mtimes}
        for folder in shared_folders:
            try:
                files, streams, mtimes = self.get_files_list(
                    folder, self.share_dbs[prefix + "mtimes"], self.share_dbs[prefix + "files"],
                    self.share_dbs[prefix + "streams"], rebuild
                )
                new_files = {**new_files, **files}
                new_streams = {**new_streams, **streams}
                new_mtimes = {**new_mtimes, **mtimes}
            except OSError as error:
                self.queue.put((_("Error while scanning folder %(path)s: %(error)s"), {
                    'path': folder,
                    'error': error
                }, None))
        self.set_shares(share_type, files=new_files, streams=new_streams, mtimes=new_mtimes)
        wordindex = self.get_files_index(new_files, prefix + "fileindex")
        self.set_shares(share_type, wordindex=wordindex)
        del wordindex
        gc.collect()
        return new_mtimes, new_files, new_streams
    def is_hidden(folder, filename=None, entry_stat=None):
        """ Stop sharing any dot/hidden directories/files """
        if filename is None:
            last_folder = os.path.basename(os.path.normpath(folder.replace('\\', '/')))
            if last_folder.startswith("."):
                return True
        if filename is not None and filename.startswith("."):
            return True
        if sys.platform == "win32":
            if len(folder) == 3 and folder[1] == ":" and folder[2] in ("\\", "/"):
                return False
            if entry_stat is None:
                if filename is not None:
                    entry_stat = os.stat(folder + '\\' + filename)
                else:
                    entry_stat = os.stat(folder)
            return entry_stat.st_file_attributes & stat.FILE_ATTRIBUTE_HIDDEN
        return False
    def get_files_index(self, sharedfiles, fileindex_dest):
        """ Update Search index with new files """
        """ We dump data directly into the file index database to save memory.
        For the word index db, we can't use the same approach, as we need to access
        dict elements frequently. This would take too long to access from disk. """
        self.share_dbs[fileindex_dest].close()
        self.share_dbs[fileindex_dest] = shelve.open(os.path.join(self.config.data_dir, fileindex_dest + ".db"),
                                                     flag='n', protocol=pickle.HIGHEST_PROTOCOL)
        wordindex = {}
        index = 0
        count = 0
        lastpercent = 0.0
        for folder in sharedfiles:
            count += 1
            percent = float("%.2f" % (count / len(sharedfiles)))
            if lastpercent < percent <= 1.0:
                self.queue.put(percent)
                lastpercent = percent
            for fileinfo in sharedfiles[folder]:
                fileinfo = list(fileinfo)
                filename = fileinfo[0]
                fileinfo[0] = folder + '\\' + filename
                self.share_dbs[fileindex_dest][repr(index)] = fileinfo
                for k in set((folder + " " + filename).lower().translate(self.translatepunctuation).split()):
                    try:
                        wordindex[k].append(index)
                    except KeyError:
                        wordindex[k] = [index]
                index += 1
        return wordindex
class Shares:
    def __init__(self, core, config, queue, init_shares=True, ui_callback=None):
        self.core = core
        self.ui_callback = ui_callback
        self.config = config
        self.queue = queue
        self.translatepunctuation = str.maketrans(dict.fromkeys(PUNCTUATION, ' '))
        self.share_dbs = {}
        self.rescanning = False
        self.should_compress_shares = False
        self.compressed_shares_normal = slskmessages.SharedFileList(None, None)
        self.compressed_shares_buddy = slskmessages.SharedFileList(None, None)
        self.convert_shares()
        self.share_db_paths = [
            ("files", os.path.join(self.config.data_dir, "files.db")),
            ("streams", os.path.join(self.config.data_dir, "streams.db")),
            ("wordindex", os.path.join(self.config.data_dir, "wordindex.db")),
            ("fileindex", os.path.join(self.config.data_dir, "fileindex.db")),
            ("mtimes", os.path.join(self.config.data_dir, "mtimes.db")),
            ("buddyfiles", os.path.join(self.config.data_dir, "buddyfiles.db")),
            ("buddystreams", os.path.join(self.config.data_dir, "buddystreams.db")),
            ("buddywordindex", os.path.join(self.config.data_dir, "buddywordindex.db")),
            ("buddyfileindex", os.path.join(self.config.data_dir, "buddyfileindex.db")),
            ("buddymtimes", os.path.join(self.config.data_dir, "buddymtimes.db"))
        ]
        if not init_shares:
            return
        self.init_shares()
    def init_shares(self):
        rescan_startup = (self.config.sections["transfers"]["rescanonstartup"]
                          and not self.config.need_config())
        self.rescan_shares(init=True, rescan=rescan_startup)
    def real2virtual(self, path):
        return self.real2virtual_cls(path, self.config)
    def real2virtual_cls(cls, path, config):
        path = path.replace('/', '\\')
        for virtual, real, *_unused in cls._virtualmapping(config):
            virtual = virtual.replace('/', '_').replace('\\', '_')
            real = real.replace('/', '\\')
            if path == real:
                return virtual
            real = real.rstrip('\\') + '\\'
            if path.startswith(real):
                virtualpath = virtual + '\\' + path[len(real):]
                return virtualpath
        return "__INTERNAL_ERROR__" + path
    def virtual2real(self, path):
        path = path.replace('/', os.sep).replace('\\', os.sep)
        for virtual, real, *_unused in self._virtualmapping(self.config):
            virtual = virtual.replace('/', '_').replace('\\', '_')
            if path == virtual:
                return real
            if path.startswith(virtual + os.sep):
                realpath = real + path[len(virtual):]
                return realpath
        return "__INTERNAL_ERROR__" + path
    def _virtualmapping(config):
        mapping = config.sections["transfers"]["shared"][:]
        mapping += config.sections["transfers"]["buddyshared"]
        return mapping
    def convert_shares(self):
        """ Convert fs-based shared to virtual shared (pre 1.4.0) """
        def _convert_to_virtual(shared_folder):
            if isinstance(shared_folder, tuple):
                return shared_folder
            virtual = shared_folder.replace('/', '_').replace('\\', '_').strip('_')
            log.add("Renaming shared folder '%s' to '%s'. A rescan of your share is required.",
                    (shared_folder, virtual))
            return (virtual, shared_folder)
        self.config.sections["transfers"]["shared"] = [_convert_to_virtual(x)
                                                       for x in self.config.sections["transfers"]["shared"]]
        self.config.sections["transfers"]["buddyshared"] = [_convert_to_virtual(x)
                                                            for x in self.config.sections["transfers"]["buddyshared"]]
    def load_shares(cls, shares, dbs, reset_shares=False):
        errors = []
        for destination, shelvefile in dbs:
            try:
                if not reset_shares:
                    shares[destination] = shelve.open(shelvefile, protocol=pickle.HIGHEST_PROTOCOL)
                else:
                    try:
                        os.remove(shelvefile)
                    except IsADirectoryError:
                        os.rmdir(shelvefile)
                    shares[destination] = shelve.open(shelvefile, flag='n', protocol=pickle.HIGHEST_PROTOCOL)
            except Exception:
                from traceback import format_exc
                shares[destination] = None
                errors.append(shelvefile)
                exception = format_exc()
        if not errors:
            return
        log.add(_("Failed to process the following databases: %(names)s"), {
            'names': '\n'.join(errors)
        })
        log.add(exception)
        if not reset_shares:
            log.add(_("Attempting to reset index of shared files due to an error. Please rescan your shares."))
            cls.load_shares(shares, dbs, reset_shares=True)
            return
        log.add(_("File index of shared files could not be accessed. This could occur due to several instances of "
                  "Nicotine+ being active simultaneously, file permission issues, or another issue in Nicotine+."))
    def file_is_shared(self, user, virtualfilename, realfilename):
        log.add_transfer("Checking if file %(virtual_name)s with real path %(path)s is shared", {
            "virtual_name": virtualfilename,
            "path": realfilename
        })
        if not os.access(realfilename, os.R_OK):
            log.add_transfer("Can't access file %(virtual_name)s with real path %(path)s, not sharing", {
                "virtual_name": virtualfilename,
                "path": realfilename
            })
            return False
        folder, _sep, file = virtualfilename.rpartition('\\')
        shared = self.share_dbs.get("files")
        bshared = self.share_dbs.get("buddyfiles")
        if bshared is not None:
            for row in self.config.sections["server"]["userlist"]:
                if row[0] != user:
                    continue
                if self.config.sections["transfers"]["buddysharestrustedonly"] and not row[4]:
                    break
                for fileinfo in bshared.get(str(folder), ""):
                    if file == fileinfo[0]:
                        return True
        if shared is not None:
            for fileinfo in shared.get(str(folder), ""):
                if file == fileinfo[0]:
                    return True
        log.add_transfer("Failed to share file %(virtual_name)s with real path %(path)s, since it wasn't found", {
            "virtual_name": virtualfilename,
            "path": realfilename
        })
        return False
    def get_compressed_shares_message(self, share_type):
        """ Returns the compressed shares message. Creates a new one if necessary, e.g.
        if an individual file was added to our shares. """
        if self.should_compress_shares:
            self.rescan_shares(init=True, rescan=False)
        if share_type == "normal":
            return self.compressed_shares_normal
        if share_type == "buddy":
            return self.compressed_shares_buddy
        return None
    def close_shares(share_dbs):
        dbs = [
            "files", "streams", "wordindex",
            "fileindex", "mtimes",
            "buddyfiles", "buddystreams", "buddywordindex",
            "buddyfileindex", "buddymtimes"
        ]
        for database in dbs:
            db_file = share_dbs.get(database)
            if db_file is not None:
                share_dbs[database].close()
                del share_dbs[database]
    def send_num_shared_folders_files(self):
        """ Send number publicly shared files to the server. """
        if not (self.core and self.core.logged_in):
            return
        try:
            shared = self.share_dbs.get("files")
            index = self.share_dbs.get("fileindex")
            if shared is None or index is None:
                return
            try:
                sharedfolders = len(shared)
                sharedfiles = len(index)
            except TypeError:
                sharedfolders = len(list(shared))
                sharedfiles = len(list(index))
            self.queue.append(slskmessages.SharedFoldersFiles(sharedfolders, sharedfiles))
        except Exception as error:
            log.add(_("Failed to send number of shared files to the server: %s"), error)
    def build_scanner_process(self, shared_folders=None, init=False, rescan=True, rebuild=False):
        import multiprocessing
        multiprocessing.set_start_method("spawn", force=True)
        scanner_queue = multiprocessing.Queue()
        scanner = Scanner(
            self.config,
            scanner_queue,
            shared_folders,
            self.share_db_paths,
            init,
            rescan,
            rebuild
        )
        scanner = multiprocessing.Process(target=scanner.run)
        scanner.daemon = True
        return scanner, scanner_queue
    def rebuild_shares(self, use_thread=True):
        return self.rescan_shares(rebuild=True, use_thread=use_thread)
    def get_shared_folders(self):
        shared_folders = self.config.sections["transfers"]["shared"][:]
        shared_folders_buddy = self.config.sections["transfers"]["buddyshared"][:]
        return (shared_folders, shared_folders_buddy)
    def process_scanner_messages(self, scanner, scanner_queue):
                item = scanner_queue.get()
                    template, args, log_level = item
                        self.compressed_shares_normal = item
                        self.compressed_shares_buddy = item
                    self.should_compress_shares = False
    def quit(self):
        self.close_shares(self.share_dbs)
class Search:
    def __init__(self, core, config, queue, share_dbs, geoip, ui_callback=None):
        self.core = core
        self.config = config
        self.queue = queue
        self.ui_callback = None
        self.searches = {}
        self.searchid = int(random.random() * (2 ** 31 - 1))
        self.wishlist_interval = 0
        self.share_dbs = share_dbs
        self.geoip = geoip
        self.translatepunctuation = str.maketrans(dict.fromkeys(PUNCTUATION, ' '))
        for term in config.sections["server"]["autosearch"]:
            search_id = self.increment_search_id()
            self.searches[search_id] = {"id": search_id, "term": term, "mode": "wishlist", "ignore": True}
        if hasattr(ui_callback, "search"):
            self.ui_callback = ui_callback.search
    def request_folder_download(self, user, folder, visible_files):
        if self.config.sections["transfers"]["reverseorder"]:
            visible_files.sort(key=lambda x: x[1], reverse=True)
        for file in visible_files:
            user, fullpath, destination, size, bitrate, length = file
            self.core.transfers.get_file(
                user, fullpath, destination,
                size=size, bitrate=bitrate, length=length)
        self.core.transfers.get_folder(user, folder)
    def add_allowed_search_id(search_id):
        """ Allow parsing search result messages for a search ID """
        slskmessages.SEARCH_TOKENS_ALLOWED.add(search_id)
    def remove_allowed_search_id(search_id):
        """ Disallow parsing search result messages for a search ID """
        slskmessages.SEARCH_TOKENS_ALLOWED.discard(search_id)
    def add_search(self, search_id, term, mode, ignore):
        self.searches[search_id] = {"id": search_id, "term": term, "mode": mode, "ignore": ignore}
        self.add_allowed_search_id(search_id)
    def remove_search(self, search_id):
        self.remove_allowed_search_id(search_id)
        search = self.searches.get(search_id)
        if search is None:
            return
        if search["term"] in self.config.sections["server"]["autosearch"]:
            search["ignore"] = True
            return
        del self.searches[search_id]
    def do_search(self, text, mode, room=None, user=None):
        processed_search = self.process_search_term(text, mode, room, user)
        if not processed_search:
            return None
        text, room, users = processed_search
        self.increment_search_id()
        searchterm_words = text.split()
        searchterm_words_special = (p for p in searchterm_words if p.startswith(('-', '*')) and len(p) > 1)
        searchterm_without_special = ' '.join(p for p in searchterm_words if not p.startswith(('-', '*')))
        if self.config.sections["searches"]["remove_special_chars"]:
            """
            Remove special characters from search term
            SoulseekQt doesn't seem to send search results if special characters are included (July 7, 2020)
            """
            stripped_searchterm = ' '.join(searchterm_without_special.translate(self.translatepunctuation).split())
            if stripped_searchterm:
                searchterm_without_special = stripped_searchterm
        searchterm = searchterm_without_special.strip()
        for word in searchterm_words_special:
            searchterm += " " + word
        if self.config.sections["searches"]["enable_history"]:
            items = self.config.sections["searches"]["history"]
            if searchterm in items:
                items.remove(searchterm)
            items.insert(0, searchterm)
            del items[200:]
            self.config.write_configuration()
        if mode == "global":
            self.do_global_search(self.searchid, searchterm)
        elif mode == "rooms":
            self.do_rooms_search(self.searchid, searchterm, room)
        elif mode == "buddies":
            self.do_buddies_search(self.searchid, searchterm)
        elif mode == "user":
            self.do_peer_search(self.searchid, searchterm, users)
        self.add_search(self.searchid, searchterm, mode, ignore=False)
        if self.ui_callback:
            self.ui_callback.do_search(self.searchid, searchterm, mode, room, user)
        return (self.searchid, searchterm, searchterm_without_special)
    def do_global_search(self, search_id, text):
        self.queue.append(slskmessages.FileSearch(search_id, text))
        """ Request a list of related searches from the server.
        Seemingly non-functional since 2018 (always receiving empty lists). """
    def do_wishlist_search(self, search_id, text):
        self.add_allowed_search_id(search_id)
        self.queue.append(slskmessages.WishlistSearch(search_id, text))
    def file_search_result(self, msg):
        if not self.ui_callback or msg.token not in slskmessages.SEARCH_TOKENS_ALLOWED:
            return
        search = self.searches.get(msg.token)
        if search is None or search["ignore"]:
            return
        conn = msg.conn
        username = conn.init.target_user
        addr = conn.addr
        if addr:
            country = self.geoip.get_country_code(addr[0])
        else:
            country = ""
        if country == "-":
            country = ""
        self.ui_callback.show_search_result(msg, username, country)
    def process_search_request(self, searchterm, user, searchid, direct=False):
        """ Note: since this section is accessed every time a search request arrives,
        several times a second, please keep it as optimized and memory
        sparse as possible! """
        if not searchterm:
            return
        if not self.config.sections["searches"]["search_results"]:
            return
        if not direct and user == self.config.sections["server"]["login"]:
            return
        maxresults = self.config.sections["searches"]["maxresults"]
        if maxresults == 0:
            return
        excluded_words = []
        partial_words = []
        if '-' in searchterm or '*' in searchterm:
            for word in searchterm.split():
                if len(word) < 1:
                    continue
                if word.startswith('-'):
                    for subword in word.translate(self.translatepunctuation).split():
                        excluded_words.append(subword)
                elif word.startswith('*'):
                    for subword in word.translate(self.translatepunctuation).split():
                        partial_words.append(subword)
        searchterm_old = searchterm
        searchterm = searchterm.lower().translate(self.translatepunctuation).strip()
        if len(searchterm) < self.config.sections["searches"]["min_search_chars"]:
            return
        checkuser, _reason = self.core.network_filter.check_user(user, None)
        if not checkuser:
            return
        if checkuser == 2:
            wordindex = self.share_dbs.get("buddywordindex")
        else:
            wordindex = self.share_dbs.get("wordindex")
        if wordindex is None:
            return
        resultlist = self.create_search_result_list(searchterm, wordindex, excluded_words, partial_words)
        if not resultlist:
            return
        if checkuser == 2:
            fileindex = self.share_dbs.get("buddyfileindex")
        else:
            fileindex = self.share_dbs.get("fileindex")
        if fileindex is None:
            return
        fileinfos = []
        numresults = min(len(resultlist), maxresults)
        for index in islice(resultlist, numresults):
            fileinfo = fileindex.get(repr(index))
            if fileinfo is not None:
                fileinfos.append(fileinfo)
        if numresults != len(fileinfos):
            log.add_debug(("File index inconsistency while responding to search request "
                           "\"%(query)s\". %(expected_num)s results expected, but only %(total_num)s "
                           "results were found in database."), {
                "query": searchterm_old,
                "expected_num": numresults,
                "total_num": len(fileinfos)
            })
        numresults = len(fileinfos)
        if not numresults:
            return
        uploadspeed = self.core.transfers.upload_speed
        queuesize = self.core.transfers.get_upload_queue_size()
        slotsavail = self.core.transfers.allow_new_uploads()
        fifoqueue = self.config.sections["transfers"]["fifoqueue"]
        message = slskmessages.FileSearchResult(
            None, self.config.sections["server"]["login"],
            searchid, fileinfos, slotsavail, uploadspeed, queuesize, fifoqueue)
        self.core.send_message_to_peer(user, message)
        if direct:
            log.add_search(
                _("User %(user)s is directly searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
        else:
            log.add_search(
                _("User %(user)s is searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
PUNCTUATION = ['!', '"', '
               '?', '@', '[', '\\', ']', '^', '_', '`', '{', '|', '}', '~', '–', '—', '‐', '’', '“', '”', '…']

class Scanner:
    def set_shares(self, share_type, files=None, streams=None, mtimes=None, wordindex=None):
        self.config.create_data_folder()
        storable_objects = [
            (files, "files"),
            (streams, "streams"),
            (mtimes, "mtimes"),
            (wordindex, "wordindex")
        ]
        for source, destination in storable_objects:
            if source is None:
                continue
            try:
                if share_type == "buddy":
                    destination = "buddy" + destination
                self.share_dbs[destination].close()
                self.share_dbs[destination] = shelve.open(os.path.join(self.config.data_dir, destination + ".db"),
                                                          flag='n', protocol=pickle.HIGHEST_PROTOCOL)
                self.share_dbs[destination].update(source)
            except Exception as error:
                self.queue.put((_("Can't save %(filename)s: %(error)s"),
                                {"filename": destination + ".db", "error": error}, None))
                return
    def rescan_dirs(self, share_type, mtimes=None, files=None, streams=None, rebuild=False):
        """
        Check for modified or new files via OS's last mtime on a directory,
        or, if rebuild is True, all directories
        """
        if share_type == "buddy":
            shared_folders = (x[1] for x in self.shared_buddy_folders)
            prefix = "buddy"
        else:
            shared_folders = (x[1] for x in self.shared_folders)
            prefix = ""
        new_files = {}
        new_streams = {}
        new_mtimes = {}
        if files is not None:
            new_files = {**files, **new_files}
        if streams is not None:
            new_streams = {**streams, **new_streams}
        if mtimes is not None:
            new_mtimes = {**mtimes, **new_mtimes}
        for folder in shared_folders:
            try:
                files, streams, mtimes = self.get_files_list(
                    folder, self.share_dbs[prefix + "mtimes"], self.share_dbs[prefix + "files"],
                    self.share_dbs[prefix + "streams"], rebuild
                )
                new_files = {**new_files, **files}
                new_streams = {**new_streams, **streams}
                new_mtimes = {**new_mtimes, **mtimes}
            except OSError as error:
                self.queue.put((_("Error while scanning folder %(path)s: %(error)s"), {
                    'path': folder,
                    'error': error
                }, None))
        self.set_shares(share_type, files=new_files, streams=new_streams, mtimes=new_mtimes)
        wordindex = self.get_files_index(new_files, prefix + "fileindex")
        self.set_shares(share_type, wordindex=wordindex)
        del wordindex
        gc.collect()
        return new_mtimes, new_files, new_streams
    def is_hidden(folder, filename=None, entry_stat=None):
        """ Stop sharing any dot/hidden directories/files """
        if filename is None:
            last_folder = os.path.basename(os.path.normpath(folder.replace('\\', '/')))
            if last_folder.startswith("."):
                return True
        if filename is not None and filename.startswith("."):
            return True
        if sys.platform == "win32":
            if len(folder) == 3 and folder[1] == ":" and folder[2] in ("\\", "/"):
                return False
            if entry_stat is None:
                if filename is not None:
                    entry_stat = os.stat(folder + '\\' + filename)
                else:
                    entry_stat = os.stat(folder)
            return entry_stat.st_file_attributes & stat.FILE_ATTRIBUTE_HIDDEN
        return False
    def get_files_index(self, sharedfiles, fileindex_dest):
        """ Update Search index with new files """
        """ We dump data directly into the file index database to save memory.
        For the word index db, we can't use the same approach, as we need to access
        dict elements frequently. This would take too long to access from disk. """
        self.share_dbs[fileindex_dest].close()
        self.share_dbs[fileindex_dest] = shelve.open(os.path.join(self.config.data_dir, fileindex_dest + ".db"),
                                                     flag='n', protocol=pickle.HIGHEST_PROTOCOL)
        wordindex = {}
        index = 0
        count = 0
        lastpercent = 0.0
        for folder in sharedfiles:
            count += 1
            percent = float("%.2f" % (count / len(sharedfiles)))
            if lastpercent < percent <= 1.0:
                self.queue.put(percent)
                lastpercent = percent
            for fileinfo in sharedfiles[folder]:
                fileinfo = list(fileinfo)
                filename = fileinfo[0]
                fileinfo[0] = folder + '\\' + filename
                self.share_dbs[fileindex_dest][repr(index)] = fileinfo
                for k in set((folder + " " + filename).lower().translate(self.translatepunctuation).split()):
                    try:
                        wordindex[k].append(index)
                    except KeyError:
                        wordindex[k] = [index]
                index += 1
        return wordindex
class Shares:
    def __init__(self, core, config, queue, init_shares=True, ui_callback=None):
        self.core = core
        self.ui_callback = ui_callback
        self.config = config
        self.queue = queue
        self.translatepunctuation = str.maketrans(dict.fromkeys(PUNCTUATION, ' '))
        self.share_dbs = {}
        self.rescanning = False
        self.should_compress_shares = False
        self.compressed_shares_normal = slskmessages.SharedFileList(None, None)
        self.compressed_shares_buddy = slskmessages.SharedFileList(None, None)
        self.convert_shares()
        self.share_db_paths = [
            ("files", os.path.join(self.config.data_dir, "files.db")),
            ("streams", os.path.join(self.config.data_dir, "streams.db")),
            ("wordindex", os.path.join(self.config.data_dir, "wordindex.db")),
            ("fileindex", os.path.join(self.config.data_dir, "fileindex.db")),
            ("mtimes", os.path.join(self.config.data_dir, "mtimes.db")),
            ("buddyfiles", os.path.join(self.config.data_dir, "buddyfiles.db")),
            ("buddystreams", os.path.join(self.config.data_dir, "buddystreams.db")),
            ("buddywordindex", os.path.join(self.config.data_dir, "buddywordindex.db")),
            ("buddyfileindex", os.path.join(self.config.data_dir, "buddyfileindex.db")),
            ("buddymtimes", os.path.join(self.config.data_dir, "buddymtimes.db"))
        ]
        if not init_shares:
            return
        self.init_shares()
    def init_shares(self):
        rescan_startup = (self.config.sections["transfers"]["rescanonstartup"]
                          and not self.config.need_config())
        self.rescan_shares(init=True, rescan=rescan_startup)
    def real2virtual(self, path):
        return self.real2virtual_cls(path, self.config)
    def real2virtual_cls(cls, path, config):
        path = path.replace('/', '\\')
        for virtual, real, *_unused in cls._virtualmapping(config):
            virtual = virtual.replace('/', '_').replace('\\', '_')
            real = real.replace('/', '\\')
            if path == real:
                return virtual
            real = real.rstrip('\\') + '\\'
            if path.startswith(real):
                virtualpath = virtual + '\\' + path[len(real):]
                return virtualpath
        return "__INTERNAL_ERROR__" + path
    def virtual2real(self, path):
        path = path.replace('/', os.sep).replace('\\', os.sep)
        for virtual, real, *_unused in self._virtualmapping(self.config):
            virtual = virtual.replace('/', '_').replace('\\', '_')
            if path == virtual:
                return real
            if path.startswith(virtual + os.sep):
                realpath = real + path[len(virtual):]
                return realpath
        return "__INTERNAL_ERROR__" + path
    def _virtualmapping(config):
        mapping = config.sections["transfers"]["shared"][:]
        mapping += config.sections["transfers"]["buddyshared"]
        return mapping
    def convert_shares(self):
        """ Convert fs-based shared to virtual shared (pre 1.4.0) """
        def _convert_to_virtual(shared_folder):
            if isinstance(shared_folder, tuple):
                return shared_folder
            virtual = shared_folder.replace('/', '_').replace('\\', '_').strip('_')
            log.add("Renaming shared folder '%s' to '%s'. A rescan of your share is required.",
                    (shared_folder, virtual))
            return (virtual, shared_folder)
        self.config.sections["transfers"]["shared"] = [_convert_to_virtual(x)
                                                       for x in self.config.sections["transfers"]["shared"]]
        self.config.sections["transfers"]["buddyshared"] = [_convert_to_virtual(x)
                                                            for x in self.config.sections["transfers"]["buddyshared"]]
    def load_shares(cls, shares, dbs, reset_shares=False):
        errors = []
        for destination, shelvefile in dbs:
            try:
                if not reset_shares:
                    shares[destination] = shelve.open(shelvefile, protocol=pickle.HIGHEST_PROTOCOL)
                else:
                    try:
                        os.remove(shelvefile)
                    except IsADirectoryError:
                        os.rmdir(shelvefile)
                    shares[destination] = shelve.open(shelvefile, flag='n', protocol=pickle.HIGHEST_PROTOCOL)
            except Exception:
                from traceback import format_exc
                shares[destination] = None
                errors.append(shelvefile)
                exception = format_exc()
        if not errors:
            return
        log.add(_("Failed to process the following databases: %(names)s"), {
            'names': '\n'.join(errors)
        })
        log.add(exception)
        if not reset_shares:
            log.add(_("Attempting to reset index of shared files due to an error. Please rescan your shares."))
            cls.load_shares(shares, dbs, reset_shares=True)
            return
        log.add(_("File index of shared files could not be accessed. This could occur due to several instances of "
                  "Nicotine+ being active simultaneously, file permission issues, or another issue in Nicotine+."))
    def file_is_shared(self, user, virtualfilename, realfilename):
        log.add_transfer("Checking if file is shared: %(virtual_name)s with real path %(path)s", {
            "virtual_name": virtualfilename,
            "path": realfilename
        })
        try:
            if not os.access(realfilename, os.R_OK):
                log.add_transfer("Cannot access file, not sharing: %(virtual_name)s with real path %(path)s", {
                    "virtual_name": virtualfilename,
                    "path": realfilename
                })
                return False
        except Exception:
            log.add_transfer(("Requested file path contains invalid characters or other errors, not sharing: "
                              "%(virtual_name)s with real path %(path)s"), {
                "virtual_name": virtualfilename,
                "path": realfilename
            })
            return False
        folder, _sep, file = virtualfilename.rpartition('\\')
        shared = self.share_dbs.get("files")
        bshared = self.share_dbs.get("buddyfiles")
        if bshared is not None:
            for row in self.config.sections["server"]["userlist"]:
                if row[0] != user:
                    continue
                if self.config.sections["transfers"]["buddysharestrustedonly"] and not row[4]:
                    break
                for fileinfo in bshared.get(str(folder), ""):
                    if file == fileinfo[0]:
                        return True
        if shared is not None:
            for fileinfo in shared.get(str(folder), ""):
                if file == fileinfo[0]:
                    return True
        log.add_transfer("Failed to share file, since it wasn't found: %(virtual_name)s with real path %(path)s", {
            "virtual_name": virtualfilename,
            "path": realfilename
        })
        return False
    def get_compressed_shares_message(self, share_type):
        """ Returns the compressed shares message. Creates a new one if necessary, e.g.
        if an individual file was added to our shares. """
        if self.should_compress_shares:
            self.rescan_shares(init=True, rescan=False)
        if share_type == "normal":
            return self.compressed_shares_normal
        if share_type == "buddy":
            return self.compressed_shares_buddy
        return None
    def close_shares(share_dbs):
        dbs = [
            "files", "streams", "wordindex",
            "fileindex", "mtimes",
            "buddyfiles", "buddystreams", "buddywordindex",
            "buddyfileindex", "buddymtimes"
        ]
        for database in dbs:
